import { Fragment, useEffect, useState } from "react";

/**
 * Where the tree's content came from.
 *
 * Two tallies, because they answer different questions and the tree records them
 * separately:
 *
 *   - **Names & text** — `sourcedFrom`, 4.03M nodes. The provenance of the name
 *     and description, which is what docs/data-sources.md tabulates.
 *   - **Dataset records** — `sourceIds`, 5.84M entries. Which dataset supplied the
 *     name. A node usually carries both, so a source can appear in either table.
 *
 * The counts are generated by `portal/scripts/aggregateSources.ts` (`make
 * sources-report`) rather than computed here: the tree holds 4.1M nodes and the
 * app only loads the order files it has navigated to, so a client-side tally
 * would silently under-report everything not yet fetched.
 */
interface SourceRow {
  id: string;
  name: string;
  url: string | null;
  identifier: string | null;
  licence: string | null;
  unresolved: boolean;
  datasets: string[];
  note: string | null;
}

interface Tally {
  nodes: number;
  families: number;
  sourcedFrom: Record<string, number>;
  sourceIds: Record<string, number>;
}

interface Report {
  generatedAt: string;
  totals: { nodes: number; families: number; kingdoms: number };
  kingdoms: Record<string, Tally>;
  sources: Record<string, SourceRow>;
}

interface Props {
  kingdom?: string;
  onClose: () => void;
}

const NUM = new Intl.NumberFormat("en-US");

export default function SourcesModal({ kingdom = "animalia", onClose }: Props) {
  const [report, setReport] = useState<Report | null>(null);
  const [failed, setFailed] = useState(false);
  const [scope, setScope] = useState<string>(kingdom);
  const [expanded, setExpanded] = useState<string | null>(null);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => { if (e.key === "Escape") { e.stopPropagation(); onClose(); } };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [onClose]);

  useEffect(() => {
    fetch("/data/sources-report.json")
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(String(r.status)))))
      .then(setReport)
      .catch(() => setFailed(true));
  }, []);

  const tally: Tally | null = report
    ? scope === "all"
      ? {
          nodes: Object.values(report.kingdoms).reduce((a, t) => a + t.nodes, 0),
          families: Object.values(report.kingdoms).reduce((a, t) => a + t.families, 0),
          sourcedFrom: sum(report.kingdoms, "sourcedFrom"),
          sourceIds: sum(report.kingdoms, "sourceIds"),
        }
      : report.kingdoms[scope] ?? null
    : null;

  const label = scope === "all" ? "All kingdoms" : scope;

  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.72)", zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: "24px" }}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: "#0f1117", border: "1px solid #1e2030", borderRadius: 10,
        width: "100%", maxWidth: 720, maxHeight: "82vh", overflowY: "auto", position: "relative",
        padding: "22px 24px 24px",
      }}>
        <button onClick={onClose} title="Close" style={{
          position: "absolute", top: 14, right: 16, background: "none", border: "none",
          color: "#666", fontSize: 18, cursor: "pointer", lineHeight: 1,
        }}>×</button>

        <div style={{ fontSize: 10, color: "#6666aa", letterSpacing: "0.12em", textTransform: "uppercase", marginBottom: 6 }}>
          Provenance
        </div>
        <h2 style={{ margin: "0 0 4px", fontSize: 17, color: "#c0c0d8", fontWeight: 400 }}>Sources</h2>

        {failed && (
          <p style={{ color: "#a08050", fontSize: 13, lineHeight: 1.6 }}>
            The source report has not been generated. Run{" "}
            <code style={{ color: "#c0c0d8" }}>make sources-report</code> in the repository root.
          </p>
        )}

        {!failed && !report && <p style={{ color: "#666", fontSize: 13 }}>Loading…</p>}

        {tally && (
          <>
            <div style={{ display: "flex", alignItems: "center", gap: 10, margin: "14px 0 4px", flexWrap: "wrap" }}>
              <select
                value={scope}
                onChange={(e) => setScope(e.target.value)}
                style={{ background: "#14161f", color: "#c0c0d8", border: "1px solid #1e2030", borderRadius: 6, padding: "4px 8px", fontSize: 12 }}
              >
                {Object.keys(report!.kingdoms).sort().map((k) => (
                  <option key={k} value={k}>{k}</option>
                ))}
                <option value="all">All kingdoms</option>
              </select>
              <span style={{ color: "#666", fontSize: 12 }}>
                {NUM.format(tally.families)} families · {NUM.format(tally.nodes)} nodes
              </span>
              <span style={{ color: "#444", fontSize: 11, marginLeft: "auto" }}>
                counted {report!.generatedAt.slice(0, 10)}
              </span>
            </div>

            <Table
              heading="Names & text"
              blurb="Provenance of each name and description, recorded per node in sourcedFrom."
              counts={tally.sourcedFrom}
              sources={report!.sources}
              expanded={expanded}
              setExpanded={setExpanded}
            />
            <Table
              heading="Dataset records"
              blurb="Which dataset supplied the name, recorded per node in sourceIds. A node usually appears in both tables."
              counts={tally.sourceIds}
              sources={report!.sources}
              expanded={expanded}
              setExpanded={setExpanded}
            />

            <p style={{ color: "#555", fontSize: 11, lineHeight: 1.6, margin: "18px 0 0" }}>
              {label} · Licences are those recorded for the dataset in{" "}
              <code style={{ color: "#777" }}>docs/data-sources.md</code>, which is also where the
              citation identifiers and the reasoning behind each import live.
            </p>
          </>
        )}
      </div>
    </div>
  );
}

function sum(kingdoms: Record<string, Tally>, field: "sourcedFrom" | "sourceIds"): Record<string, number> {
  const out: Record<string, number> = {};
  for (const t of Object.values(kingdoms)) {
    for (const [k, v] of Object.entries(t[field])) out[k] = (out[k] ?? 0) + v;
  }
  return out;
}

function Table({ heading, blurb, counts, sources, expanded, setExpanded }: {
  heading: string;
  blurb: string;
  counts: Record<string, number>;
  sources: Record<string, SourceRow>;
  expanded: string | null;
  setExpanded: (id: string | null) => void;
}) {
  const rows = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  if (rows.length === 0) return null;

  return (
    <div style={{ marginTop: 20 }}>
      <div style={{ fontSize: 11, color: "#c0c0d8", letterSpacing: "0.08em", textTransform: "uppercase" }}>{heading}</div>
      <p style={{ margin: "4px 0 8px", color: "#555", fontSize: 11, lineHeight: 1.5 }}>{blurb}</p>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
        <thead>
          <tr style={{ color: "#555", textAlign: "left", fontSize: 10, textTransform: "uppercase", letterSpacing: "0.08em" }}>
            <th style={{ fontWeight: 400, padding: "4px 8px 4px 0" }}>Source</th>
            <th style={{ fontWeight: 400, padding: "4px 8px", textAlign: "right", width: 90 }}>Nodes</th>
            <th style={{ fontWeight: 400, padding: "4px 0 4px 8px" }}>Licence</th>
          </tr>
        </thead>
        <tbody>
          {rows.map(([id, count]) => {
            const s = sources[id];
            const open = expanded === id;
            return (
              <Fragment key={id}>
                <tr style={{ borderTop: "1px solid #161823", cursor: s?.datasets?.length ? "pointer" : "default" }}
                    onClick={() => s?.datasets?.length && setExpanded(open ? null : id)}>
                  <td style={{ padding: "5px 8px 5px 0", color: "#c0c0d8" }}>
                    {s?.url ? (
                      <a href={s.url} target="_blank" rel="noreferrer noopener" style={{ color: "#8a8ac0" }} onClick={(e) => e.stopPropagation()}>{s.name}</a>
                    ) : (
                      <span>{s?.name ?? id}</span>
                    )}
                    {s?.datasets?.length ? (
                      <span style={{ color: "#444", fontSize: 10, marginLeft: 6 }}>
                        {open ? "▾" : "▸"} {s.datasets.length} dataset{s.datasets.length === 1 ? "" : "s"}
                      </span>
                    ) : null}
                  </td>
                  <td style={{ padding: "5px 8px", textAlign: "right", color: "#888", fontVariantNumeric: "tabular-nums" }}>{NUM.format(count)}</td>
                  <td style={{ padding: "5px 0 5px 8px", color: s?.licence ? "#666" : "#7a6040" }}>
                    {s?.licence ?? (s?.unresolved ? "not recorded" : "—")}
                  </td>
                </tr>
                {open && s?.datasets?.length ? (
                  <tr>
                    <td colSpan={3} style={{ padding: "0 0 8px 0", color: "#555", fontSize: 11, lineHeight: 1.7 }}>
                      {s.datasets.map((d) => d).join(" · ")}
                      {s.note ? <div style={{ color: "#4a4a55", marginTop: 3 }}>{s.note}</div> : null}
                    </td>
                  </tr>
                ) : null}
              </Fragment>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}